create or replace function private.can_read_business_review(p_business_id uuid,p_customer_id uuid,p_appointment_id uuid) returns boolean language sql stable security definer set search_path='' as $$ select p_customer_id=(select auth.uid()) or exists(select 1 from public.businesses b where b.id=p_business_id and b.owner_id=(select auth.uid())) or exists(select 1 from public.appointments a join public.employees e on e.id=a.employee_id where a.id=p_appointment_id and e.user_id=(select auth.uid()) and e.is_active) $$;